{
  "answer_type": "grounded_answer",
  "answer": "LIWC is incorporated into the LAXARY system as a modified model that calculates possible scores for each survey question using the PTSD Linguistic Dictionary. This approach allows for fine-grained discrimination of physiological and psychological health markers of PTSD without the need for expensive laboratory testing or traditional surveys, thereby gaining the trust of clinicians who expect to see conventional survey results from the PTSD assessment.",
  "citations": ["E2"],
  "claim_table": [
    {
      "claim": "LAXARY includes a modified LIWC model.",
      "support": "The modified LIWC model calculates possible scores of each survey question using the PTSD Linguistic Dictionary.",
